import{_ as t,o as a,c as d,ag as o}from"./chunks/framework.BuUvxvtQ.js";const u=JSON.parse('{"title":"Health checks","description":"","frontmatter":{},"headers":[],"relativePath":"api/health.md","filePath":"api/health.md"}'),r={name:"api/health.md"};function s(c,e,i,n,h,l){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="health-checks" tabindex="-1">Health checks <a class="header-anchor" href="#health-checks" aria-label="Permalink to &quot;Health checks&quot;">​</a></h1><p>Health endpoints provide read-only connectivity diagnostics. They require no API key, return no account data and do not consume API credits.</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Checks</th></tr></thead><tbody><tr><td><code>GET /api/v1/health</code></td><td>Combined database, hosted AI and weather status</td></tr><tr><td><code>GET /api/v1/health/db</code></td><td>Database reachability without returning records</td></tr><tr><td><code>GET /api/v1/health/ai</code></td><td>Hosted AI model-list connectivity, without generating text</td></tr><tr><td><code>GET /api/v1/health/weather</code></td><td>Open-Meteo connectivity</td></tr></tbody></table><h2 id="request" tabindex="-1">Request <a class="header-anchor" href="#request" aria-label="Permalink to &quot;Request&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://skystyle.app/api/v1/health</span></span></code></pre></div><p>The AI endpoint optionally accepts <code>?provider=openai</code>, <code>?provider=gemini</code> or <code>?provider=mistral</code>. Weather accepts <code>?provider=open-meteo</code>. An unsupported filter returns HTTP 400.</p><h2 id="reading-the-response" tabindex="-1">Reading the response <a class="header-anchor" href="#reading-the-response" aria-label="Permalink to &quot;Reading the response&quot;">​</a></h2><p>The combined response includes:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>ok</code>, <code>degraded</code> or <code>unconfigured</code></td></tr><tr><td><code>healthy</code></td><td>True only when all required categories are healthy</td></tr><tr><td><code>responseTime</code></td><td>Time to serve the diagnostic, in milliseconds</td></tr><tr><td><code>checkedAt</code></td><td>Oldest category measurement time</td></tr><tr><td><code>cached</code></td><td>Whether all category measurements came from the probe cache</td></tr><tr><td><code>services</code></td><td>Per-category status, measurement time, response time and cache state</td></tr></tbody></table><p>HTTP 200 means the diagnostic was returned successfully. Monitor the JSON <code>status</code> or <code>healthy</code> field to decide whether services are reachable. One unavailable category gives <code>degraded</code>; all categories missing configuration gives <code>unconfigured</code>.</p><h2 id="cache-and-scope" tabindex="-1">Cache and scope <a class="header-anchor" href="#cache-and-scope" aria-label="Permalink to &quot;Cache and scope&quot;">​</a></h2><p>Provider checks have a four-second timeout. Measurements and CDN responses may be cached for up to five minutes. <code>checkedAt</code> is the measurement time, not necessarily the time you sent the request.</p><p>AI probes list models rather than generate recommendations. Weather probes check Open-Meteo and do not verify paid weather providers. Results do not establish BYOK availability, data accuracy or an uptime guarantee. Credentials and raw provider errors are excluded.</p>',13)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
